<?php
namespace App\AI\Providers; use App\AI\AIProviderInterface;
final class OpenAICompatibleProvider implements AIProviderInterface { public function __construct(private array $cfg){} public function name(): string { return $this->cfg['name'] ?? 'OpenAI-compatible'; } public function generate(array $messages,array $options=[]): array { $url=rtrim($this->cfg['base_url'] ?? 'https://api.openai.com/v1','/').'/chat/completions'; $body=['model'=>$this->cfg['model'],'messages'=>$messages,'temperature'=>(float)($options['temperature'] ?? $this->cfg['temperature'] ?? .4),'max_tokens'=>(int)($options['max_tokens'] ?? $this->cfg['max_tokens'] ?? 800),'response_format'=>$options['response_format'] ?? ['type'=>'json_object']]; $ch=curl_init($url); curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_POST=>true,CURLOPT_HTTPHEADER=>['Content-Type: application/json','Authorization: Bearer '.$this->cfg['api_key']],CURLOPT_POSTFIELDS=>json_encode($body),CURLOPT_TIMEOUT=>45]); $raw=curl_exec($ch); $code=curl_getinfo($ch,CURLINFO_HTTP_CODE); $err=curl_error($ch); curl_close($ch); if($raw===false||$code>=400) throw new \RuntimeException($err ?: 'AI provider HTTP '.$code); $json=json_decode($raw,true) ?: []; return ['text'=>$json['choices'][0]['message']['content'] ?? '', 'usage'=>$json['usage'] ?? [], 'raw'=>$json]; }}
